"use client";

import {
  Box,
  Flex,
  Toaster as ChakraToaster,
  Heading,
  Portal,
  Spinner,
  Toast,
} from "@chakra-ui/react";
import type { IconDefinition } from "@fortawesome/fontawesome-svg-core";
import { useCallback } from "react";
import { CircleCheck, CircleInfo, Icon } from "../Icon";
import type { ToastMeta } from "../types/toast";
import { toaster } from "./toasterInstance";

const iconSlotStyles = {
  boxSize: "5",
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  flexShrink: 0,
} as const;

export const Toaster = () => {
  const renderIcon = useCallback((type: string, icon?: IconDefinition) => {
    if (icon) {
      return <Icon icon={icon} />;
    }
    if (type === "loading") {
      return <Spinner size="sm" />;
    }
    if (type === "success") {
      return <Icon icon={CircleCheck} />;
    }
    return <Icon icon={CircleInfo} />;
  }, []);

  return (
    <Portal>
      <ChakraToaster toaster={toaster} insetInline={{ mdDown: "4" }} data-testid="toaster">
        {(toast) => {
          const meta = toast.meta as ToastMeta | undefined;
          const showIcon = meta?.iconStart !== false;
          const renderTitleAndDescription = toast.title && toast.description;
          const singleLineText = renderTitleAndDescription
            ? null
            : (toast.description ?? toast.title);

          const iconSlot = showIcon ? (
            <Box {...iconSlotStyles}>{renderIcon(toast.type || "", meta?.icon)}</Box>
          ) : null;

          return (
            <Toast.Root width={{ md: "sm" }}>
              {renderTitleAndDescription ? (
                <Box
                  display="grid"
                  gridTemplateColumns={showIcon ? "auto 1fr" : "1fr"}
                  columnGap="3"
                  rowGap="1.5"
                  flex="1"
                  minW="0"
                >
                  {iconSlot && (
                    <Box gridColumn="1" gridRow="1" alignSelf="center">
                      {iconSlot}
                    </Box>
                  )}
                  <Box gridColumn={showIcon ? 2 : 1} gridRow={1} minW="0">
                    <Toast.Title asChild>
                      <Heading>{toast.title}</Heading>
                    </Toast.Title>
                  </Box>
                  <Box gridColumn={showIcon ? 2 : 1} gridRow={2} minW="0">
                    <Toast.Description>{toast.description}</Toast.Description>
                  </Box>
                </Box>
              ) : (
                <Flex flex="1" gap="3" align="center" minW="0">
                  {iconSlot}
                  {singleLineText && (
                    <Toast.Description flex="1" minW="0">
                      {singleLineText}
                    </Toast.Description>
                  )}
                </Flex>
              )}
              <Flex gap="2" shrink="0" align="center">
                {toast.action && <Toast.ActionTrigger>{toast.action.label}</Toast.ActionTrigger>}
                {toast.closable !== false && <Toast.CloseTrigger />}
              </Flex>
            </Toast.Root>
          );
        }}
      </ChakraToaster>
    </Portal>
  );
};
